// @title PBR Surface Renderer
// @param specPower 32.0 1.0 128.0 "Specular Hardness"
// @param heightScale 0.5 0.001 2.0 "Normal Height"
// @primaryButton settings

uniform sampler2D iChannel0;
uniform float specPower;
uniform float heightScale;

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    vec2 texel = 1.0 / iResolution.xy;

    // Sample chemical B concentration for height mapping
    float h = texture(iChannel0, uv).g;
    float hL = texture(iChannel0, uv - vec2(texel.x, 0.0)).g;
    float hR = texture(iChannel0, uv + vec2(texel.x, 0.0)).g;
    float hD = texture(iChannel0, uv - vec2(0.0, texel.y)).g;
    float hU = texture(iChannel0, uv + vec2(0.0, texel.y)).g;

    // Calculate Normals from gradient
    vec3 normal = normalize(vec3((hL - hR) * heightScale, (hD - hU) * heightScale, 0.1));

    // Basic Lighting
    vec3 lightPos = vec3(0.5, 0.5, 2.0);
    vec3 viewPos = vec3(0.5, 0.5, 5.0);
    vec3 fragPos = vec3(uv, h * 0.2);

    vec3 lightDir = normalize(lightPos - fragPos);
    vec3 viewDir = normalize(viewPos - fragPos);
    vec3 halfDir = normalize(lightDir + viewDir);

    // Diffuse
    float diff = max(dot(normal, lightDir), 0.0);

    // Specular
    float spec = pow(max(dot(normal, halfDir), 0.0), specPower);

    // Color Mapping based on concentration
    vec3 albedo = mix(vec3(0.05, 0.02, 0.1), vec3(0.0, 0.8, 0.9), h);
    if(h > 0.5) albedo = mix(albedo, vec3(1.0, 0.9, 0.5), (h - 0.5) * 2.0);

    vec3 ambient = vec3(0.02);
    vec3 color = ambient + (albedo * diff) + (vec3(1.0) * spec * 0.5);

    // Gamma correction
    color = pow(color, vec3(1.0/2.2));

    fragColor = vec4(color, 1.0);
}

// @title Gray-Scott Painter
// @format rgba32f
// @param brushSize 20.0 1.0 100.0 "Brush Size"
// @param feed 0.037 0.010 0.100 "Feed rate"
// @param kill 0.060 0.030 0.071 "Kill rate"
// @param speed 1.0 0.1 4.0 "Simulation speed"
// @primaryButton settings

uniform sampler2D iChannel0;
uniform float brushSize;
uniform float feed;
uniform float kill;
uniform float speed;

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    vec2 texel = 1.0 / iResolution.xy;

    // Feedback sample (Current state of chemicals A and B)
    // R channel = Chemical A, G channel = Chemical B
    vec4 center = texture(iChannel0, uv);

    // Initial state: Fill with Chemical A
    if (iFrame < 10) {
        fragColor = vec4(1.0, 0.0, 0.0, 1.0);
        return;
    }

    // 3x3 Laplacian calculation for diffusion
    vec4 l = texture(iChannel0, uv + vec2(-texel.x, 0.0));
    vec4 r = texture(iChannel0, uv + vec2(texel.x, 0.0));
    vec4 u = texture(iChannel0, uv + vec2(0.0, texel.y));
    vec4 d = texture(iChannel0, uv + vec2(0.0, -texel.y));

    vec4 ul = texture(iChannel0, uv + vec2(-texel.x, texel.y));
    vec4 ur = texture(iChannel0, uv + vec2(texel.x, texel.y));
    vec4 dl = texture(iChannel0, uv + vec2(-texel.x, -texel.y));
    vec4 dr = texture(iChannel0, uv + vec2(texel.x, -texel.y));

    // Discrete Laplacian operator weights
    vec4 lap = (l + r + u + d) * 0.2 + (ul + ur + dl + dr) * 0.05 - center;

    float a = center.r;
    float b = center.g;

    // Mouse Interaction: Paint Chemical B into the system
    if (iMouse.z > 0.0) {
        float dist = length(fragCoord.xy - iMouse.xy);
        float brush = smoothstep(brushSize, brushSize * 0.5, dist);
        // Inject B and displace A
        b = mix(b, 1.0, brush);
        a = mix(a, 0.0, brush);
    }

    // Gray-Scott Reaction-Diffusion Math
    float reaction = a * b * b;

    // da/dt = Da * lap(a) - a*b^2 + feed * (1 - a)
    float da = (1.0 * lap.r - reaction + feed * (1.0 - a)) * speed;

    // db/dt = Db * lap(b) + a*b^2 - (kill + feed) * b
    float db = (0.5 * lap.g + reaction - (kill + feed) * b) * speed;

    // Output updated state clamped to [0, 1]
    fragColor = vec4(clamp(a + da, 0.0, 1.0), clamp(b + db, 0.0, 1.0), 0.0, 1.0);
}

setPortCount(1, 1)
onPointer(data => send(data))

function draw() {
  ctx.clearRect(0, 0, width, height)

  if (mouse.down) {
    ctx.fillStyle = `rgba(255, 255, 255, 0.3)`
    ctx.beginPath()
    ctx.arc(mouse.x * width, mouse.y * height, 30, 0, Math.PI * 2)
    ctx.fill()
  }
}

setSize(320, 480);
noDrag();
setTitle('RD Lab');

// Configure ports: 0 inlets, 3 outlets
// Outlet 0: Full metadata object
// Outlet 1: Feed (float)
// Outlet 2: Kill (float)
setPortCount(0, 3);

// Gray-Scott Reaction-Diffusion Presets
const presets = [
  { name: 'Mitosis / Bacteria', feed: 0.0367, kill: 0.0649 },
  { name: 'Coral Growth', feed: 0.0400, kill: 0.0600 },
  { name: 'Fingerprints', feed: 0.0370, kill: 0.0600 },
  { name: 'Spirals', feed: 0.0180, kill: 0.0510 },
  { name: 'Worms', feed: 0.0580, kill: 0.0650 },
  { name: 'Pulsating Solids', feed: 0.0250, kill: 0.0600 },
  { name: 'Moving Spots', feed: 0.0140, kill: 0.0540 },
  { name: 'U-Skate World', feed: 0.0620, kill: 0.0610 },
  { name: 'Waves', feed: 0.0100, kill: 0.0450 },
  { name: 'Chaos', feed: 0.0260, kill: 0.0510 }
];

createApp({
  setup() {
    const activeIndex = ref(null);

    const selectPreset = (p, index) => {
      activeIndex.value = index;

      // Dispatching to multiple outlets
      send({ type: 'params', feed: p.feed, kill: p.kill, name: p.name }, { to: 0 });
      send(p.feed, { to: 1 });
      send(p.kill, { to: 2 });
    };

    return { presets, selectPreset, activeIndex };
  },
  template: `
    <div class="h-full w-full bg-zinc-950 text-zinc-300 font-mono p-4 overflow-hidden border-2 border-zinc-800 rounded-lg flex flex-col">
      <div class="mb-4 border-b border-emerald-900/30 pb-3">
        <div class="flex justify-between items-start">
          <div>
            <h1 class="text-[11px] font-bold text-emerald-500 uppercase tracking-[0.2em]">Gray-Scott Lab</h1>
            <p class="text-[9px] text-zinc-500 mt-0.5">Split-Channel Calibration</p>
          </div>
          <div class="text-[8px] px-1.5 py-0.5 bg-emerald-500/10 text-emerald-500 border border-emerald-500/20 rounded">
            MULTI-OUT
          </div>
        </div>
      </div>

      <div class="flex-1 overflow-y-auto pr-2 custom-scrollbar space-y-2 nopan nowheel">
        <div 
          v-for="(p, idx) in presets" 
          :key="p.name" 
          @click="selectPreset(p, idx)"
          class="nodrag group cursor-pointer border border-zinc-800 p-2 transition-all duration-200"
          :class="activeIndex === idx ? 'bg-emerald-500/5 border-emerald-500/40' : 'bg-zinc-900/50 hover:border-zinc-600'"
        >
          <div class="flex justify-between items-center mb-2">
            <span class="text-[10px] uppercase tracking-wider transition-colors"
                  :class="activeIndex === idx ? 'text-emerald-400' : 'text-zinc-400 group-hover:text-zinc-200'">
              {{ p.name }}
            </span>
            <div v-if="activeIndex === idx" class="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]"></div>
          </div>

          <div class="flex gap-1">
            <div class="flex-1 bg-black/40 p-1.5 border border-zinc-800/50 relative overflow-hidden">
              <div class="text-[7px] text-zinc-600 uppercase tracking-tighter mb-0.5 relative z-10">Feed [O1]</div>
              <div class="text-[11px] font-bold tabular-nums relative z-10"
                   :class="activeIndex === idx ? 'text-emerald-300' : 'text-zinc-300'">
                {{ p.feed.toFixed(4) }}
              </div>
              <div class="absolute bottom-0 left-0 h-[2px] bg-emerald-500/30 transition-all" :style="{ width: (p.feed * 1000) + '%' }"></div>
            </div>
            <div class="flex-1 bg-black/40 p-1.5 border border-zinc-800/50 relative overflow-hidden">
              <div class="text-[7px] text-zinc-600 uppercase tracking-tighter mb-0.5 relative z-10">Kill [O2]</div>
              <div class="text-[11px] font-bold tabular-nums relative z-10"
                   :class="activeIndex === idx ? 'text-emerald-300' : 'text-zinc-300'">
                {{ p.kill.toFixed(4) }}
              </div>
              <div class="absolute bottom-0 left-0 h-[2px] bg-emerald-500/30 transition-all" :style="{ width: (p.kill * 1000) + '%' }"></div>
            </div>
          </div>
        </div>
      </div>

      <div class="mt-4 pt-2 border-t border-zinc-900 grid grid-cols-2 gap-2 text-[7px] text-zinc-600">
        <div class="flex items-center gap-1">
          <span class="w-1 h-1 bg-zinc-700"></span> OUT 1: f(float)
        </div>
        <div class="flex items-center gap-1">
          <span class="w-1 h-1 bg-zinc-700"></span> OUT 2: k(float)
        </div>
      </div>

      <style>
        .custom-scrollbar::-webkit-scrollbar {
          width: 3px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: rgba(0,0,0,0.1);
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #27272a;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #10b981;
        }
      </style>
    </div>
  `
}).mount(root);
